"""Select once from all initial steady recipes; never retry rejected series."""
import pathlib,json,hashlib
R=pathlib.Path(__file__).resolve().parent;B=R.parent;load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
e=load(R/'job-exit.json');assert e['returncode']==0 and not pathlib.Path('/proc',str(e['pid'])).exists();assert not(R/'selection-audit.json').exists()
a=load(R/'native-raw-audit.json');assert a['passed'] and a['points']==23 and a['raw_dispatches']==92 and a['edge_data_excluded_from_performance_map']
q=load(R/'pipeline-candidates.json');ref=load(R/'reference-map.json');analysis=load(R/'analysis/pipeline-map.json');assert len(q['candidates'])==len(analysis['candidates'])==5
oldzero=load(B/'single-tg-continuation-20261023/published/zero-physical-spill-alternatives-round192.json');assert oldzero['passed'] and len(oldzero['validated_recipes'])==1 and oldzero['validated_recipes'][0]['resource_alternative_validated'];previous=oldzero['validated_recipes'][0];previous_initial=previous['initial']['mmac_theoretical_fraction']
rows=[];perf=[];resources=[]
for c in q['candidates']:
 old=next(x for x in ref['best_64k'] if x['tile']==c['tile'] and x['layout']==c['layout']);ratio=c['mmac_theoretical_fraction']/old['mmac_theoretical_fraction'];zero=all(c['physical'][k]==0 for k in ['private_segment_fixed_size','vgpr_spill_count','sgpr_spill_count'])
 ar=next(x for x in analysis['candidates'] if x['source_ids']==c['source_ids']);assert ar['mmac_theoretical_fraction']==c['mmac_theoretical_fraction'] and ar['intermediate_residual_fraction_of_long_time']==c['intermediate_residual_fraction_of_long_time']
 rows.append(dict(config=c['config'],fraction=c['mmac_theoretical_fraction'],residual=c['intermediate_residual_fraction_of_long_time'],steady=c['steady'],physical=c['physical'],relative_to_64KiB_best=ratio,all_physical_zero=zero,source_ids=c['source_ids']))
 if c['steady'] and ratio>=1.03:perf.append(c)
 if c['steady'] and zero and ratio>=.98 and c['mmac_theoretical_fraction']>previous_initial:resources.append(c)
perf_nominees=[max(perf,key=lambda x:x['mmac_theoretical_fraction'])] if perf else [];resource_nominees=[max(resources,key=lambda x:x['mmac_theoretical_fraction'])] if resources else []
nominees={tuple(x['source_ids']):x for x in perf_nominees+resource_nominees}
out=dict(passed=True,raw_audit_sha256=sha(R/'native-raw-audit.json'),candidate_sha256=sha(R/'pipeline-candidates.json'),analysis_sha256=sha(R/'analysis/pipeline-map.json'),rows=rows,performance_eligible=len(perf),performance_nominees=len(perf_nominees),resource_eligible=len(resources),resource_alternative_nominees=len(resource_nominees),nominees=list(nominees.values()),performance_source_ids=[x['source_ids'] for x in perf_nominees],resource_source_ids=[x['source_ids'] for x in resource_nominees],prior_confirmed_zero_initial_fraction=previous_initial,prior_confirmed_zero_fresh_fraction=previous['fresh']['mmac_theoretical_fraction'],prior_zero_report_sha256=sha(B/'single-tg-continuation-20261023/published/zero-physical-spill-alternatives-round192.json'),policy='One fastest initial steady >=3% performance candidate; one fastest steady physical-zero candidate >=98% same-budget best and faster than existing confirmed zero recipe initial. Deduplicate nominees; exactly one independent series each. Nonsteady or dominated recipes receive no repeats. Edge-only data excluded.',map_unchanged=True)
(R/'selection-audit.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(dict(passed=True,performance_nominees=len(perf_nominees),resource_nominees=len(resource_nominees),fresh_series=len(nominees),steady=sum(x['steady'] for x in rows),best_initial_fraction=max(x['fraction'] for x in rows),best_steady_fraction=max((x['fraction'] for x in rows if x['steady']),default=None),best_steady_zero_fraction=max((x['fraction'] for x in rows if x['steady'] and x['all_physical_zero']),default=None))))
